/**
 * Configuration type for container split variables
 */
export type ContainerSplitVariableType = {
    /** Order in which the variable appears */
    order?: number;
    /** Indicates whether the variable is active */
    active?: boolean;
    /** Disable automatic slot fill based on user contex */
    disableInitialSlotFill?: boolean;
};
/**
 * A Variable for a container split field (used for creating columns within a container).
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the container split variable including:
 *   * **order**? - Order in which the variable appears
 *   * **active**? - Indicates whether the variable is active
 *   * **disableInitialSlotFill**? - Disable automatic slot fill based on user context
 */
export declare function ContainerSplitVariable(config: ContainerSplitVariableType): ContainerSplitVariableType;
